140 : func (s *BoltStore) AddObserveEvent(e *observe.Event) error {
141 : 	// New measurements use one estimator, independently of legacy handler estimates.
142 : 	if e.Attrs["accounting_version"] == "1" {
143 : 		e.Tokens = 0
144 : 		e.Attrs["token_estimator"] = memory.TextEstimator
145 : 		for _, key := range []string{"payload_bytes", "argument_bytes"} {
146 : 			if _, ok := memory.MeasuredBytes(e.Attrs, key); !ok {
147 : 				delete(e.Attrs, key)
148 : 			}
149 : 		}
150 : 		if n, ok := memory.MeasuredBytes(e.Attrs, "payload_bytes"); ok {
151 : 			e.Tokens = int(memory.EstimateTextTokens(n))
152 : 		}
153 : 	}
154 : 
155 : 	if isModelUsage(e) && e.Attrs["usage_time_basis"] == "source" {
156 : 		if at, err := time.Parse(time.RFC3339Nano, e.Attrs["usage_source_time"]); err == nil && !at.IsZero() {
157 : 			e.Timestamp = at
158 : 		}
159 : 	}
160 : 	if e.ID == "" {
161 : 		e.ID = ulid.Make().String()
162 : 	}
163 : 	if e.Timestamp.IsZero() {
164 : 		e.Timestamp = time.Now()
165 : 	}
166 : 	return s.db.Update(func(tx *bolt.Tx) error {
167 : 		b := tx.Bucket(BucketObserveEvents)
168 : 		// Only explicit origin identity deduplicates; equal commands are valid calls.
169 : 		if usageOrigin(e) != "" || memory.HasObservationIdentity(e.SessionID, e.Attrs) {
170 : 			origin := []string{e.SessionID, e.Attrs["host"], e.Attrs["actor_id"], e.Attrs["invocation_id"], e.Attrs["observation_stage"]}
171 : 			if claim, ok := workHostClaim(e); ok {
172 : 				// Equal receipt retries still deduplicate. Contradictory receipts
173 : 				// must survive so attribution cannot silently select the first.
174 : 				origin = append(origin, "aide/work:1", claim.id, claim.tool, claim.hash)
175 : 			}
176 : 			if usage := usageOrigin(e); usage != "" {
177 : 				origin = []string{usage}
178 : 			}
179 : 			identity, err := json.Marshal(origin)
180 : 			if err != nil {
181 : 				return err
182 : 			}
183 : 			key := []byte(fmt.Sprintf("%x", sha256.Sum256(identity)))
184 : 			origins, err := tx.CreateBucketIfNotExists([]byte("observe_origins"))
185 : 			if err != nil {
186 : 				return err
187 : 			}
188 : 			if id := origins.Get(key); id != nil {
189 : 				if data := b.Get(id); data != nil {
190 : 					if isModelUsage(e) {
191 : 						var prior observe.Event
192 : 						if err := json.Unmarshal(data, &prior); err != nil {
193 : 							return err
194 : 						}
195 : 						if e.Timestamp.Before(prior.Timestamp) {
196 : 							e.ID = prior.ID
197 : 							updated, err := json.Marshal(e)
198 : 							if err != nil {
199 : 								return err
200 : 							}
201 : 							return b.Put([]byte(e.ID), updated)
202 : 						}
203 : 					}
204 : 					// Keep the first observation and its timestamp stable on retries.
205 : 					return json.Unmarshal(data, e)
206 : 				}
207 : 			}
208 : 			if err := origins.Put(key, []byte(e.ID)); err != nil {
