68  : 	stats := &memory.TokenStats{
69  : 		Accounting:   memory.NewTokenAccounting(),
70  : 		ByTool:       make(map[string]int),
71  : 		CallsByTool:  make(map[string]int),
72  : 		SavedByTool:  make(map[string]int),
73  : 		BySavingType: make(map[string]int),
74  : 		ByDelivery:   make(map[string]int),
75  : 	}
76  : 	sessions := make(map[string]bool)
77  : 	activity := newTokenActivity(since, until)
78  : 	retrievals := newTokenRetrievals(sessionID, since, until)
79  : 	stats.Accounting.Work = memory.NewTokenWork()
80  : 	usage := newModelUsage()
81  : 
82  : 	tally := func(e *memory.TokenEvent) {
83  : 		if !since.IsZero() && e.Timestamp.Before(since) {
84  : 			return
85  : 		}
86  : 		if !until.IsZero() && e.Timestamp.After(until) {
87  : 			return
88  : 		}
89  : 		if sessionID != "" && e.SessionID != sessionID {
90  : 			return
91  : 		}
92  : 
93  : 		stats.EventCount++
94  : 		if e.SessionID != "" {
95  : 			sessions[e.SessionID] = true
96  : 		}
97  : 		stats.Accounting.Add(e)
98  : 		if e.EventType == "transformation" {
99  : 			return
100 : 		}
101 : 		activity.add(e)
102 : 
103 : 		// Every event with a tool counts as one call. Injection events
104 : 		// reuse Tool for the source name; the chart filters those out.
105 : 		if e.Tool != "" && e.EventType != memory.TokenEventContextInjected {
106 : 			stats.CallsByTool[e.Tool]++
107 : 			if e.TokensSaved > 0 {
108 : 				stats.SavedByTool[e.Tool] += e.TokensSaved
109 : 			}
110 : 		}
111 : 
112 : 		switch e.EventType {
113 : 		case memory.TokenEventRead:
114 : 			stats.TotalRead += e.Tokens
115 : 			stats.ByTool[e.Tool] += e.Tokens
116 : 			stats.ReadCount++
117 : 		case memory.TokenEventOutlineUsed:
118 : 			stats.TotalRead += e.Tokens
119 : 			stats.TotalSaved += e.TokensSaved
120 : 			stats.ByTool[e.Tool] += e.Tokens
121 : 			stats.BySavingType["outline"] += e.TokensSaved
122 : 			stats.CodeToolCount++
123 : 		case memory.TokenEventSymbolRead:
124 : 			stats.TotalRead += e.Tokens
125 : 			stats.TotalSaved += e.TokensSaved
126 : 			stats.ByTool[e.Tool] += e.Tokens
127 : 			stats.BySavingType["symbol_read"] += e.TokensSaved
128 : 			stats.CodeToolCount++
129 : 		case memory.TokenEventReadAvoided:
130 : 			stats.TotalSaved += e.TokensSaved
131 : 			stats.BySavingType["read_avoided"] += e.TokensSaved
132 : 		case memory.TokenEventContextInjected:
133 : 			stats.TotalDelivered += e.Tokens
134 : 			if e.Tool != "" {
135 : 				stats.ByDelivery[e.Tool] += e.Tokens
136 : 			}
137 : 		case "modify", "write", "edit":
138 : 			if e.Attrs["accounting_version"] == "1" {
139 : 				if n, ok := memory.MeasuredBytes(e.Attrs, "argument_bytes"); ok {
140 : 					stats.TotalWritten += int(memory.EstimateTextTokens(n))
141 : 				}
142 : 				stats.TotalRead += e.Tokens
143 : 			} else {
